mapper.select:
SELECT TO_CHAR(S.REG_DATE, 'YYYY-MM-DD HH24:MI:SS') AS regDate, S.USER_NO AS userNo, U.ID AS userId, U.NICKNAME AS userNickname, S.FRAGMENT_NO AS fragmentNo, SUBSTRING(CAST(F.CONTENT AS VARCHAR), 1, 80) AS fragmentContent FROM MB_FRAGMENT_SCRAP S INNER JOIN MB_USER U ON U.USER_NO = S.USER_NO INNER JOIN MB_FRAGMENT F ON F.FRAGMENT_NO = S.FRAGMENT_NO WHERE TO_CHAR(S.REG_DATE, 'YYYY-MM-DD') = #{date}
AND ( UPPER(U.ID) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.NICKNAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(CAST(F.CONTENT AS VARCHAR)) LIKE '%' || UPPER(#{keyword}) || '%' )
ORDER BY S.REG_DATE DESC OFFSET #{offset} ROWS FETCH NEXT 20 ROWS ONLY
